using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ConjureAction", menuName = "Data/Battle/Battle Actions/Orion/Conjure Action")]
public class ConjureAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private bool enableBasedOnEffect;

	[SerializeField]
	[ShowIf("enableBasedOnEffect")]
	private Effect activateStarBasedEffect;

	[SerializeField]
	[ShowIf("enableBasedOnEffect")]
	private float effectMultiplier;

	[Header("Aquarian Puzzle Workaround")]
	[SerializeField]
	private bool lastStarActivationWithDelay;

	[SerializeField]
	[ShowIf("lastStarActivationWithDelay")]
	private VoidEvent OnActivateLastStarActivationWithDelay;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	[Header("Extra Action")]
	[SerializeField]
	private bool enableBattleActionBeforeConjure;

	[SerializeField]
	[ShowIf("enableBattleActionBeforeConjure")]
	private BattleAction battleActionBeforeConjure;

	[SerializeField]
	[ShowIf("enableBattleActionBeforeConjure")]
	private OmenLogic battleActionBeforeConjureOmenLogic;

	[Header("Righteous Conjuration")]
	[SerializeField]
	private bool righteousConjuration;

	public int EffectDivider => Mathf.CeilToInt(1f / effectMultiplier);

	public bool EnableBattleActionBeforeConjure => enableBattleActionBeforeConjure;

	public BattleAction BattleActionBeforeConjure => battleActionBeforeConjure;

	public override bool CheckConditionToBeCasted(int amount)
	{
		if (enableBattleActionBeforeConjure)
		{
			return true;
		}
		if (!enableBasedOnEffect)
		{
			return true;
		}
		return GetActivateAmount(amount) > 0;
	}

	public int GetActivateAmount(int amount)
	{
		if (!enableBasedOnEffect)
		{
			return amount;
		}
		return Mathf.CeilToInt((float)(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsEffectActiveGetAmount(activateStarBasedEffect, activateFeedback: false) + amount) * effectMultiplier);
	}

	public override void CastAmount(int amount, GameObject source)
	{
		CastTargetAmount(null, amount, source);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (enableBattleActionBeforeConjure)
		{
			if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(source, amount));
			}
			else
			{
				battleActionBeforeConjureOmenLogic.ActivateOmen(battleActionBeforeConjure, amount, target, source);
				if (righteousConjuration)
				{
					amount = 0;
				}
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(NonVFXCoroutine(source, amount));
			}
		}
		else
		{
			if (lastStarActivationWithDelay)
			{
				OnActivateLastStarActivationWithDelay.Raise();
			}
			if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(source, amount));
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(NonVFXCoroutine(source, amount));
			}
		}
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	public override void Cast(GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(source, 0));
		}
		else
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(NonVFXCoroutine(source, 0));
		}
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator VFXCoroutine(GameObject source, int amount)
	{
		SpawnVFXOnPlayerPosition(4f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		if (enableBattleActionBeforeConjure)
		{
			battleActionBeforeConjureOmenLogic.ActivateOmen(battleActionBeforeConjure, amount, null, source);
		}
		if (righteousConjuration)
		{
			amount = 0;
		}
		yield return new WaitForSeconds(vfxDelay);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(ReferenceSingleton<BattleHandler>.Instance.GetOrionAstrarium(source).ActivateStarAbility(GetActivateAmount(amount)));
	}

	private IEnumerator NonVFXCoroutine(GameObject source, int amount)
	{
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(ReferenceSingleton<BattleHandler>.Instance.GetOrionAstrarium(source).ActivateStarAbility(GetActivateAmount(amount)));
	}
}
